/*
 * prog54_topo_sort.c
 *
 * Re‑implementation of the original program (topological sort) whose
 * binary was analysed.  The program reads its parameters from the command
 * line, validates them, builds a directed graph (maximum 8 vertices) and
 * prints a topological ordering if one exists.
 *
 *   prog54_topo_sort N M u1 v1 u2 v2 ... uM vM
 *
 *   N – number of vertices (0 … 8)
 *   M – number of directed edges (0 … 8)
 *   ui vi – an edge from ui to vi (0 ≤ ui,vi < N)
 *
 * Output
 *   * a space‑separated list of the vertices in a topological order,
 *     terminated by a newline;
 *   * the string "CYCLE" (followed by a newline) if the graph contains a
 *     cycle;
 *   * the string "INVALID_INPUT" (followed by a newline) if the command
 *     line arguments are malformed or out of the allowed range.
 *
 * The implementation follows the classic Kahn algorithm and matches the
 * strings and formatting used by the original binary (puts for the two
 * messages, printf("%d") for each vertex, putchar(' ') between vertices,
 * and putchar('\\n') at the end).
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8          /* maximum number of vertices allowed */
#define MAXE 8          /* maximum number of edges allowed */

int main(int argc, char *argv[])
{
    /* ---------- input validation ---------- */
    if (argc < 3) {                     /* need at least N and M */
        puts("INVALID_INPUT");
        return 1;
    }

    /* parse N and M */
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n < 0 || n > MAXV) {
        puts("INVALID_INPUT");
        return 1;
    }

    long m = strtol(argv[2], &endptr, 10);
    if (*endptr != '\0' || m < 0 || m > MAXE) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* we expect exactly 2*m additional arguments (the edges) */
    if (argc != 3 + 2 * m) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* ---------- graph construction ---------- */
    int adj[MAXV][MAXV] = {0};   /* adjacency matrix */
    int indeg[MAXV] = {0};       /* indegree of each vertex */

    for (long i = 0; i < m; ++i) {
        long u = strtol(argv[3 + 2 * i], &endptr, 10);
        if (*endptr != '\0' || u < 0 || u >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        long v = strtol(argv[3 + 2 * i + 1], &endptr, 10);
        if (*endptr != '\0' || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }

        /* store edge u -> v (ignore duplicate edges) */
        if (!adj[u][v]) {
            adj[u][v] = 1;
            ++indeg[v];
        }
    }

    /* ---------- Kahn's topological sort ---------- */
    int queue[MAXV];
    int qhead = 0, qtail = 0;
    int processed = 0;

    /* initialise queue with all vertices of indegree 0 */
    for (int v = 0; v < n; ++v) {
        if (indeg[v] == 0) {
            queue[qtail++] = v;
        }
    }

    while (qhead < qtail) {
        int v = queue[qhead++];
        /* output the vertex */
        printf("%d", v);
        ++processed;
        if (processed < n) {
            putchar(' ');
        }

        /* remove v and update neighbours */
        for (int w = 0; w < n; ++w) {
            if (adj[v][w]) {
                --indeg[w];
                if (indeg[w] == 0) {
                    queue[qtail++] = w;
                }
            }
        }
    }

    putchar('\n');

    if (processed != n) {
        /* not all vertices were processed → cycle */
        puts("CYCLE");
        return 1;
    }

    return 0;
}
